    {"type": "hybrid_retriever", "category": "retriever", "name": "Hybrid Retriever", "description": "Combines dense vector and BM25 keyword retrieval. +26-31% NDCG vs dense-only", "config_schema": {"type": "object", "properties": {"top_k": {"type": "integer", "default": 20, "minimum": 1, "maximum": 1000, "description": "Documents to retrieve"}, "alpha": {"type": "number", "default": 0.6, "minimum": 0.0, "maximum": 1.0, "description": "Dense weight (1.0=all dense, 0.0=all sparse). Optimal: 0.6-0.7"}, "fusion_method": {"type": "string", "enum": ["rrf", "weighted_sum", "convex_combination"], "default": "rrf", "description": "Score fusion method"}, "rrf_k": {"type": "integer", "default": 60, "minimum": 1, "description": "RRF smoothing constant"}, "bm25_k1": {"type": "number", "default": 1.2, "minimum": 0.0, "maximum": 3.0, "description": "BM25 term frequency saturation"}, "bm25_b": {"type": "number", "default": 0.75, "minimum": 0.0, "maximum": 1.0, "description": "BM25 length normalization"}, "embedding_model": {"type": "string", "default": "openai", "description": "Embedding model for dense component"}, "normalize_scores": {"type": "boolean", "default": True, "description": "Normalize scores before fusion"}, "use_mmr": {"type": "boolean", "default": False, "description": "Apply MMR for diversity"}, "mmr_lambda": {"type": "number", "default": 0.5, "minimum": 0.0, "maximum": 1.0, "description": "MMR trade-off"}}}, "input_ports": [{"name": "query", "type": "string"}, {"name": "embeddings", "type": "embedding_list"}], "output_ports": [{"name": "documents", "type": "document_list"}]},
