    {"type": "reflection_agent", "category": "agent", "name": "Reflection Agent", "description": "Evaluates response quality and triggers retry. Self-RAG / RAG-HAT style", "config_schema": {"type": "object", "properties": {"llm_model": {"type": "string", "default": "gpt-4o-mini", "description": "LLM for evaluation"}, "min_quality_score": {"type": "number", "default": 6.0, "minimum": 0.0, "maximum": 10.0, "description": "Minimum quality score (1-10)"}, "max_retries": {"type": "integer", "default": 3, "minimum": 0, "description": "Max retry attempts"}, "critique_dimensions": {"type": "array", "items": {"type": "string"}, "default": ["faithfulness", "relevance", "completeness", "coherence"], "description": "Evaluation dimensions"}, "hallucination_detection": {"type": "string", "enum": ["llm_judge", "nli_model", "self_consistency", "none"], "default": "llm_judge", "description": "Hallucination detection method"}}}, "input_ports": [{"name": "query", "type": "string"}, {"name": "response", "type": "string"}], "output_ports": [{"name": "score", "type": "number"}, {"name": "feedback", "type": "string"}]},
