async def get_all_components(db: AsyncSession, *, redis=None) -> list[Component]:
    """Return all registered component definitions."""
    if redis:
        from ..cache import cache_get, cache_set, TTL_STATIC
        cached = cache_get(redis, "comp", "_global", "list")
        if cached is not None:
            return cached
    result = await db.execute(select(Component).order_by(Component.category, Component.name))
    rows = list(result.scalars().all())
    if redis:
        from ..cache import cache_set, TTL_STATIC
        data = [{"type": c.type, "category": c.category, "name": c.name,
                 "description": c.description, "config_schema": c.config_schema,
                 "input_ports": c.input_ports, "output_ports": c.output_ports,
                 "source": getattr(c, "source", "seed"),
                 "is_composite": getattr(c, "is_composite", False),
                 "steps": getattr(c, "steps", None),
                 "workspace_id": getattr(c, "workspace_id", "_global"),
                 } for c in rows]
        cache_set(redis, "comp", "_global", data, suffix="list", ttl=TTL_STATIC)
    return rows


async def get_component(db: AsyncSession, component_type: str, *, redis=None) -> Component | None:
    """Return a single component definition by type, or None if not found."""
    if redis:
        from ..cache import cache_get, cache_set, TTL_STATIC
        cached = cache_get(redis, "comp", "_global", component_type)
        if cached is not None:
            return cached
    result = await db.execute(select(Component).where(Component.type == component_type))
    comp = result.scalar_one_or_none()
    if comp and redis:
        from ..cache import cache_set, TTL_STATIC
        data = {"type": comp.type, "category": comp.category, "name": comp.name,
                "description": comp.description, "config_schema": comp.config_schema,
                "input_ports": comp.input_ports, "output_ports": comp.output_ports,
                "source": getattr(comp, "source", "seed"),
                "is_composite": getattr(comp, "is_composite", False),
                "steps": getattr(comp, "steps", None),
                "workspace_id": getattr(comp, "workspace_id", "_global"),
                }
        cache_set(redis, "comp", "_global", data, suffix=component_type, ttl=TTL_STATIC)
    return comp


async def get_components_by_category(db: AsyncSession, category: str) -> list[Component]:
    """Return all components for a given category."""
    result = await db.execute(select(Component).where(Component.category == category))
    return list(result.scalars().all())


async def upsert_custom_component(
    db: AsyncSession,
    *,
    type: str,
    category: str,
    name: str,
    description: str = "",
    config_schema: dict | None = None,
    input_ports: list | None = None,
    output_ports: list | None = None,
    is_composite: bool = False,
    steps: list | None = None,
    source: str = "custom",
    workspace_id: str,
    file_path: str | None = None,
    file_hash: str | None = None,
) -> Component:
    """Insert or update a custom component."""
    stmt = select(Component).where(
        Component.type == type, Component.workspace_id == workspace_id
    )
    result = await db.execute(stmt)
    existing = result.scalar_one_or_none()

    if existing:
        existing.category = category
        existing.name = name
        existing.description = description
        existing.config_schema = config_schema or {}
        existing.input_ports = input_ports or []
        existing.output_ports = output_ports or []
        existing.is_composite = is_composite
        existing.steps = steps
        existing.source = source
        existing.file_path = file_path
        existing.file_hash = file_hash
        await db.commit()
        await db.refresh(existing)
        return existing

    comp = Component(
        type=type,
        category=category,
        name=name,
        description=description,
        config_schema=config_schema or {},
        input_ports=input_ports or [],
        output_ports=output_ports or [],
        is_composite=is_composite,
        steps=steps,
        source=source,
        workspace_id=workspace_id,
        file_path=file_path,
        file_hash=file_hash,
    )
    db.add(comp)
    await db.commit()
    await db.refresh(comp)
    return comp


async def delete_component(
    db: AsyncSession, component_type: str, workspace_id: str, *, redis=None
) -> bool:
    """Delete a custom component. Returns True if deleted."""
    stmt = select(Component).where(
        Component.type == component_type,
        Component.workspace_id == workspace_id,
        Component.source == "custom",
    )
    result = await db.execute(stmt)
    comp = result.scalar_one_or_none()
    if comp:
        await db.delete(comp)
        await db.commit()
        if redis:
            await redis.delete("components:all")
        return True
    return False


async def get_seed_component(db: AsyncSession, component_type: str) -> Component | None:
    """Check if a seed component exists with this type."""
    stmt = select(Component).where(
        Component.type == component_type,
        Component.workspace_id == "_global",
    )
    result = await db.execute(stmt)
    return result.scalar_one_or_none()
